/**
 * Phase 22 Part 3 "Recommendation Engine" — prioritised, evidence-backed
 * suggestions built ONLY from the `StudentContext` snapshot (`ContextEngine.ts`)
 * plus the two existing engines that already phrase actions in natural
 * language (`todayEngine.ts`'s `getTodayRecommendations`/`getTodaysClasses`,
 * still save-based since they're pre-existing, unmodified APIs) — nothing
 * here re-ranks a module/assessment itself; `priority.ts`'s scores and
 * `PriorityReason` breakdowns are reused verbatim as evidence.
 *
 * Every recommendation is a candidate generated by one independent rule
 * (Part 3's own examples: review today's lecture, take a short break,
 * visit the library, finish a subject's task, organise the room, prepare
 * for an upcoming assessment). Candidates are pooled and sorted by
 * priority — never a single first-match ladder — because "generate
 * prioritised recommendations" implies a ranked LIST, not one line.
 * Nothing is fabricated: a rule that has no supporting evidence in this
 * save simply produces no candidate.
 */

import { getTodayRecommendations, getTodaysClasses } from "../lib/todayEngine";
import { levelFromScore, type ConfidenceLevel, CONFIDENCE_LEVEL_LABELS } from "./ConfidenceModel";
import type { PriorityReason } from "../lib/priority";
import type { StudentContext } from "./ContextEngine";
import type { UniGameSaveData } from "../types/domain";

export type RecommendationCategory =
  | "overdue"
  | "assessment-prep"
  | "module-work"
  | "lecture-review"
  | "subject-focus"
  | "take-a-break"
  | "organise-room"
  | "visit-library"
  | "streak";

export interface Recommendation {
  id: string;
  category: RecommendationCategory;
  /** 0-100, highest first. */
  priority: number;
  action: string;
  reason: string;
  estimatedDurationMinutes: number;
  /** How strongly this save's OWN data backs the suggestion — the same 5-tier vocabulary as Part 2's subject confidence, reused for a different score (see `ConfidenceModel.ts`'s `levelFromScore`). */
  confidence: ConfidenceLevel;
  confidenceLabel: string;
  /** Same shape as `priority.ts`'s `PriorityReason` — an honest, additive breakdown a player can be shown verbatim (Part 8's "Why?"). */
  evidence: PriorityReason[];
  subjectId: string | null;
}

function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function makeRecommendation(
  id: string,
  category: RecommendationCategory,
  priority: number,
  action: string,
  reason: string,
  estimatedDurationMinutes: number,
  evidence: PriorityReason[],
  subjectId: string | null
): Recommendation {
  const confidence = levelFromScore(clamp(priority, 0, 100));
  return { id, category, priority: clamp(priority, 0, 100), action, reason, estimatedDurationMinutes, confidence, confidenceLabel: CONFIDENCE_LEVEL_LABELS[confidence], evidence, subjectId };
}

function overdueRecommendations(context: StudentContext): Recommendation[] {
  return context.overdueAssessments.map((item) =>
    makeRecommendation(
      `overdue-${item.assessmentId}`,
      "overdue",
      100,
      `${item.title} is overdue — submit it as soon as you can`,
      `${item.title} (${item.subjectName}) passed its due date ${item.daysOverdue} day${item.daysOverdue === 1 ? "" : "s"} ago.`,
      45,
      [{ label: `Overdue by ${item.daysOverdue} day${item.daysOverdue === 1 ? "" : "s"}`, contribution: 100, max: 100 }],
      item.subjectId
    )
  );
}

/** "Prepare for tomorrow's assessment" — Part 3's own example, for anything due within 2 days. */
function assessmentPrepRecommendations(context: StudentContext): Recommendation[] {
  return context.upcomingAssessments
    .filter((item) => item.daysUntilDue <= 2)
    .map((item) => {
      const priority = item.daysUntilDue === 0 ? 95 : item.daysUntilDue === 1 ? 85 : 70;
      return makeRecommendation(
        `prep-${item.assessmentId}`,
        "assessment-prep",
        priority,
        item.daysUntilDue <= 1 ? `Prepare for ${item.title} — due ${item.daysUntilDue === 0 ? "today" : "tomorrow"}` : `Start preparing for ${item.title}`,
        `${item.title} (${item.subjectName}) is due in ${item.daysUntilDue} day${item.daysUntilDue === 1 ? "" : "s"}.`,
        60,
        [{ label: `Due in ${item.daysUntilDue} day${item.daysUntilDue === 1 ? "" : "s"}`, contribution: priority, max: 100 }],
        item.subjectId
      );
    });
}

/** The existing, already-ranked "what to work on next" engine, reused verbatim (never re-ranked here). */
function moduleWorkRecommendations(save: UniGameSaveData, now: Date): Recommendation[] {
  return getTodayRecommendations(save, now, 3).map((rec) => {
    const priority = rec.item.priority.score;
    const subjectId = rec.item.subject.id;
    return makeRecommendation(
      `today-${rec.item.type}-${rec.item.type === "module" ? rec.item.module.id : rec.item.assessment.id}`,
      rec.item.type === "assessment" ? "assessment-prep" : "module-work",
      priority,
      rec.action,
      `${rec.item.subject.name}'s highest-priority item right now.`,
      rec.item.type === "assessment" ? 60 : 35,
      rec.item.priority.reasons,
      subjectId
    );
  });
}

/** "Review today's lecture" — Part 3's own example, only when a real scheduled class exists today. */
function lectureReviewRecommendations(save: UniGameSaveData, now: Date): Recommendation[] {
  return getTodaysClasses(save, now)
    .slice(0, 1)
    .map((cls) =>
      makeRecommendation(
        `lecture-${cls.entry.id}`,
        "lecture-review",
        55,
        `Review today's lecture — ${cls.moduleTitle}`,
        `${cls.subjectName} has ${cls.moduleTitle} scheduled today.`,
        20,
        [{ label: "Scheduled today", contribution: 55, max: 100 }],
        cls.subjectId
      )
    );
}

/** "Cloud Computing has received less study time this week than your other subjects" — Part 4's own example line, generated here as a recommendation with real evidence, only when there's genuine separation (never a coin-flip between close subjects). */
function subjectFocusRecommendation(context: StudentContext): Recommendation[] {
  if (context.subjects.length < 2) return [];
  const ranked = [...context.subjects].sort((a, b) => a.focusMinutesLast7Days - b.focusMinutesLast7Days);
  const least = ranked[0];
  const rest = ranked.slice(1);
  const restAverage = rest.reduce((sum, s) => sum + s.focusMinutesLast7Days, 0) / rest.length;
  if (restAverage - least.focusMinutesLast7Days < 20) return []; // not enough real separation to single one out
  const priority = clamp(50 + (restAverage - least.focusMinutesLast7Days) * 0.5, 50, 90);
  return [
    makeRecommendation(
      `subject-focus-${least.subjectId}`,
      "subject-focus",
      priority,
      `Spend some time on ${least.subjectName} today`,
      `${least.subjectName} has received less study time this week (${least.focusMinutesLast7Days} min) than your other subjects (avg ${Math.round(restAverage)} min).`,
      30,
      [
        { label: `${least.subjectName}: ${least.focusMinutesLast7Days} min this week`, contribution: 0, max: 100 },
        { label: `Other subjects average: ${Math.round(restAverage)} min`, contribution: Math.round(priority), max: 100 },
      ],
      least.subjectId
    ),
  ];
}

function takeABreakRecommendation(context: StudentContext): Recommendation[] {
  if (context.streak.current < 14) return [];
  return [
    makeRecommendation(
      "take-a-break",
      "take-a-break",
      65,
      "Take a short break",
      `You've maintained a ${context.streak.current}-day study streak — a lighter day is fine too.`,
      15,
      [{ label: `${context.streak.current}-day streak`, contribution: 65, max: 100 }],
      null
    ),
  ];
}

function organiseRoomRecommendation(context: StudentContext): Recommendation[] {
  if (context.roomUnlockProgress.unlockedCount > 0 || context.roomUnlockProgress.totalCount === 0) return [];
  return [
    makeRecommendation(
      "organise-room",
      "organise-room",
      40,
      "Organise your study room",
      "Your room hasn't unlocked any furniture yet — a Focus Sprint or two would change that.",
      20,
      [{ label: "0 furniture items unlocked", contribution: 40, max: 100 }],
      null
    ),
  ];
}

/** "Visit the library" — only when it's genuinely the least-visited real campus location among ones the player HAS visited at all (never suggested on a save with zero visit history, which would be a fabricated nudge). */
function visitLibraryRecommendation(context: StudentContext): Recommendation[] {
  const libraryVisit = context.buildingVisitHistory["library"];
  const anyVisits = Object.values(context.buildingVisitHistory).some((v) => v.visitDays > 0);
  if (!anyVisits) return [];
  const libraryDays = libraryVisit?.visitDays ?? 0;
  const isLeastVisited = context.favouriteBuildings.every((f) => f.location.id === "library" || f.visitDays > libraryDays);
  if (libraryDays > 1 || !isLeastVisited) return [];
  return [
    makeRecommendation(
      "visit-library",
      "visit-library",
      35,
      "Visit the library",
      libraryDays === 0 ? "You haven't visited the Library yet this semester." : "You've visited the Library less than your other regular spots.",
      15,
      [{ label: `Library visit days: ${libraryDays}`, contribution: 35, max: 100 }],
      null
    ),
  ];
}

/**
 * Every applicable candidate, pooled and sorted by priority — the "generate
 * prioritised recommendations" the brief asks for. `save` is only used for
 * the two pre-existing phrasing engines (`todayEngine.ts`); every other
 * signal comes from `context`.
 */
export function generateRecommendations(save: UniGameSaveData, context: StudentContext, now: Date = new Date(), limit = 6): Recommendation[] {
  const candidates: Recommendation[] = [
    ...overdueRecommendations(context),
    ...assessmentPrepRecommendations(context),
    ...moduleWorkRecommendations(save, now),
    ...lectureReviewRecommendations(save, now),
    ...subjectFocusRecommendation(context),
    ...takeABreakRecommendation(context),
    ...organiseRoomRecommendation(context),
    ...visitLibraryRecommendation(context),
  ];

  return candidates.sort((a, b) => b.priority - a.priority).slice(0, limit);
}
